1	package posemap
2	
3	import (
4		"math"
5		"sort"
6	)
7	
8	// Correct 提交一次已确认回环校正。
9	//
10	// req.ID 必须非空；req.Anchor 必须准确命中一个已导入帧的时间（不能是
11	// 初始位姿，也不借用历史查询得到的最近一帧）；目标位姿数值必须有限、
12	// 目标方差必须非负。命中后，锚点帧采用提交的位姿；从锚点到提交时末帧
13	// 的轨迹整体平移并旋转（保持这些帧在校正前彼此的相对位置与朝向，时间
14	// 不变，朝向归一到既有范围）；锚点之后每帧的方差等于目标方差加上锚点
15	// 之后至该帧的原运动方差累计值。更早的位姿不变。
16	//
17	// 受影响帧中的路标观测随新位姿改变地图位置；更早观测的地图位置不变。
18	// 同一路标仍按全部已接受观测、依原时间与同帧输入次序做增量平均并遵守
19	// 合并距离限制；观测次数不变。若校正后出现路标冲突，整次校正拒绝并说
20	// 明冲突帧时间与路标。输入或校正结果含非有限数值同样拒绝；观测转换到
21	// 地图坐标后溢出为 NaN/无穷时按数值异常拒绝，说明该观测所在帧的实际
22	// 时间、路标标识与出现编号，而不是误报为距离冲突。
23	//
24	// 同一标识以相同内容重复提交返回首次结果且不再修改数据；同一标识不同
25	// 内容明确拒绝。任何拒绝或保存失败都不改变轨迹、路标与既有校正记录。
26	// 旧文件缺少逐帧观测来源时，覆盖其历史范围的校正返回 RejectNoBasis。
27	func (m *Map) Correct(req Correction) (CorrectionRecord, error) {
28		m.mu.Lock()
29		defer m.mu.Unlock()
30		if m.closed {
31			return CorrectionRecord{}, ErrClosed
32		}
33		st := m.state
34	
35		// 已保存校正：相同内容直接返回首次记录；不同内容明确拒绝。
36		// 不做任何校验或状态变更，即使其后又提交过其他校正。
37		if hash, ok := st.corrIndex[req.ID]; ok {
38			if hash == canonicalCorrectionHash(req.Anchor, req.Target) {
39				return cloneRecord(st.correctionRecordByID(req.ID)), nil
40			}
41			return CorrectionRecord{}, &RejectError{Kind: RejectCorrectionMismatch, Landmark: req.ID, HasLandmark: true}
42		}
43	
44		if req.ID == "" {
45			return CorrectionRecord{}, &RejectError{Kind: RejectEmptyID}
46		}
47		tgt := req.Target
48		if !isFinite(tgt.X) || !isFinite(tgt.Y) || !isFinite(tgt.Heading) || !isFinite(tgt.Variance) {
49			return CorrectionRecord{}, &RejectError{Kind: RejectNonFinite, Time: req.Anchor, HasTime: true}
50		}
51		if tgt.Variance < 0 {
52			return CorrectionRecord{}, &RejectError{Kind: RejectNegativeVariance, Time: req.Anchor, HasTime: true}
53		}
54	
55		// 锚点必须准确命中已导入帧：trajectory[0] 是初始位姿，不能校正。
56		anchorIdx := -1
57		for j := 1; j < len(st.trajectory); j++ {
58			if st.trajectory[j].Time == req.Anchor {
59				anchorIdx = j
60				break
61			}
62		}
63		if anchorIdx < 0 {
64			return CorrectionRecord{}, &RejectError{Kind: RejectAnchorNotFound, Time: req.Anchor, HasTime: true}
65		}
66		end := len(st.trajectory) - 1
67	
68		// 受影响范围内每一帧都必须有逐帧依据（旧文件没有，不能靠推测校正）。
69		for k := anchorIdx - 1; k < len(st.sources); k++ {
70			if st.sources[k] == nil {
71				return CorrectionRecord{}, &RejectError{Kind: RejectNoBasis, Time: req.Anchor, HasTime: true}
72			}
73		}
74	
75		oldAnchor := st.trajectory[anchorIdx]
76		newHeading := normalizeAngle(tgt.Heading)
77		// 相对位姿整体旋转 δ；平移锚点到目标位置。
78		dHeading := normalizeAngle(newHeading - oldAnchor.Heading)
79		cosD, sinD := math.Cos(dHeading), math.Sin(dHeading)
80		// 目标位置与朝向与锚点当前值一致（朝向按角度等价比较：δ 归一后为 0）
81		// 时是只改方差的恒等校正：几何上没有任何平移或旋转，校正前后位姿必须
82		// 完全相同。此时仍套用旋转平移公式会先求 old-oldAnchor 的相对偏移，当
83		// 轨迹横跨 ±1e308 这类大坐标时该差值先溢出为 ±Inf、再参与浮点运算退化
84		// 为 NaN，使本应成功的校正被误判为 non_finite。恒等校正直接保留原位姿，
85		// 只按累计规则更新方差。
86		identity := dHeading == 0 && tgt.X == oldAnchor.X && tgt.Y == oldAnchor.Y
87	
88		// ---- 在副本上推演新位姿，真实状态此时保持不变 ----
89		next := append([]Pose(nil), st.trajectory...)
90		accumVar := tgt.Variance
91		for j := anchorIdx; j <= end; j++ {
92			old := st.trajectory[j]
93			if j > anchorIdx {
94				accumVar += st.sources[j-1].moveVariance
95			}
96			var np Pose
97			if identity {
98				np = Pose{
99					Time:     old.Time,
100					X:        old.X,
101					Y:        old.Y,
102					Heading:  old.Heading,
103					Variance: accumVar,
104				}
105			} else {
106				dx := old.X - oldAnchor.X
107				dy := old.Y - oldAnchor.Y
108				np = Pose{
109					Time:     old.Time,
110					X:        tgt.X + cosD*dx - sinD*dy,
111					Y:        tgt.Y + sinD*dx + cosD*dy,
112					Heading:  normalizeAngle(old.Heading + dHeading),
113					Variance: accumVar,
114				}
115			}
116			if !isFinite(np.X) || !isFinite(np.Y) || !isFinite(np.Heading) || !isFinite(np.Variance) {
117				return CorrectionRecord{}, &RejectError{Kind: RejectNonFinite, Time: req.Anchor, HasTime: true}
118			}
119			next[j] = np
120		}
121	
122		// occKey 标识某一路标的某一次出现。回环校正跨越同一路标的多次出现
123		// 时，各次出现分别聚合、分别遵守合并距离限制。观测按所在帧时间归入
124		// 当时的那次出现，时间边界规则与打开文件时的归属校验共享（见
125		// occurrence.go）；已接受观测必然属于某次出现。
126		type occKey struct {
127			id  string
128			num int
129		}
130	
131		// 受影响的路标出现：在受影响帧中被观测到的全部（标识，出现编号）。
132		affected := make(map[occKey]struct{})
133		for j := anchorIdx; j <= end; j++ {
134			t := st.trajectory[j].Time
135			for _, ob := range st.sources[j-1].observations {
136				affected[occKey{id: ob.ID, num: st.landmarks[ob.ID].occurrenceAt(t)}] = struct{}{}
137			}
138		}
139		affectedKeys := make([]occKey, 0, len(affected))
140		for k := range affected {
141			affectedKeys = append(affectedKeys, k)
142		}
143		sort.Slice(affectedKeys, func(i, j int) bool {
144			if affectedKeys[i].id != affectedKeys[j].id {
145				return affectedKeys[i].id < affectedKeys[j].id
146			}
147			return affectedKeys[i].num < affectedKeys[j].num
148		})
149	
150		// 逐“出现”运行聚合：旧文件第 1 次出现的既有观测作为固定“旧贡献”
151		// 起点（位置不随校正改变），其余观测按帧时间与同帧输入次序、以当前/
152		// 校正后位姿重放，接纳与合并规则（转换、非有限优先、首条建点、距离
153		// 判定、增量平均、计数）与导入共享同一实现（见 aggregate.go）。同一路
154		// 标的不同出现互不参与彼此的合并。
155		aggs := make(map[occKey]*observationAgg, len(affectedKeys))
156		for _, k := range affectedKeys {
157			occ := st.landmarks[k.id].appearances[k.num-1]
158			a := &observationAgg{}
159			if occ.legacyCount > 0 {
160				// 旧文件第 1 次出现：固定旧贡献作为聚合起点，不随后续校正改变。
161				a.seed(occ.legacyCount, occ.legacyMX, occ.legacyMY)
162			}
163			aggs[k] = a
164		}
165		for j := 1; j <= end; j++ {
166			src := st.sources[j-1]
167			if src == nil {
168				continue // 旧文件帧：观测已计入对应出现的 legacy 起点
169			}
170			pose := next[j]
171			t := st.trajectory[j].Time
172			for _, ob := range src.observations {
173				k := occKey{id: ob.ID, num: st.landmarks[ob.ID].occurrenceAt(t)}
174				a, ok := aggs[k]
175				if !ok {
176					continue
177				}
178				// 目标、原始观测与校正后位姿都有限，转换结果仍可能因数值过大
179				// 溢出为 NaN/无穷。与导入一致：数值异常优先于距离冲突，按
180				// non_finite 拒绝并指出该观测所在帧的实际时间、路标标识与
181				// 其所属的出现编号（不是锚点时间），无论该次出现此前是否已有
182				// 观测、记录仍有效还是已失效。
183				switch a.admit(pose, ob, st.config.MergeDistance) {
184				case obsNonFinite:
185					return CorrectionRecord{}, &RejectError{
186						Kind:          RejectNonFinite,
187						Time:          st.trajectory[j].Time,
188						HasTime:       true,
189						Landmark:      ob.ID,
190						HasLandmark:   true,
191						Occurrence:    k.num,
192						HasOccurrence: true,
193					}
194				case obsConflict:
195					return CorrectionRecord{}, &RejectError{
196						Kind:          RejectLandmarkConflict,
197						Time:          st.trajectory[j].Time,
198						HasTime:       true,
199						Landmark:      ob.ID,
200						HasLandmark:   true,
201						Occurrence:    k.num,
202						HasOccurrence: true,
203					}
204				}
205			}
206		}
207		for _, k := range affectedKeys {
208			a := aggs[k]
209			occ := st.landmarks[k.id].appearances[k.num-1]
210			if !isFinite(a.x) || !isFinite(a.y) {
211				return CorrectionRecord{}, &RejectError{Kind: RejectNonFinite, Time: req.Anchor, HasTime: true}
212			}
213			if a.count != occ.count {
214				// 内存不变量被破坏不可能由本包写出，按损坏处理而非半提交。
215				return CorrectionRecord{}, ErrCorrupt
216			}
217		}
218	
219		// ---- 组装校正前后快照（记录不可变） ----
220		rec := &CorrectionRecord{
221			ID:        req.ID,
222			Anchor:    req.Anchor,
223			Target:    tgt,
224			EndTime:   st.trajectory[end].Time,
225			Poses:     make([]PoseChange, 0, end-anchorIdx+1),
226			Landmarks: make([]LandmarkChange, 0, len(affectedKeys)),
227		}
228		for j := anchorIdx; j <= end; j++ {
229			rec.Poses = append(rec.Poses, PoseChange{Before: st.trajectory[j], After: next[j]})
230		}
231		for _, k := range affectedKeys {
232			occ := st.landmarks[k.id].appearances[k.num-1]
233			a := aggs[k]
234			rec.Landmarks = append(rec.Landmarks, LandmarkChange{
235				ID:         k.id,
236				Occurrence: k.num,
237				Before:     Landmark{ID: k.id, X: occ.x, Y: occ.y, Count: occ.count},
238				After:      Landmark{ID: k.id, X: a.x, Y: a.y, Count: a.count},
239			})
240		}
241	
242		// ---- 全部校验通过：暂存提交并落盘；落盘失败精确回滚 ----
243		oldTraj := append([]Pose(nil), st.trajectory...)
244		type occSnapshot struct {
245			key  occKey
246			occ  *occurrenceState
247			x, y float64
248		}
249		oldOcc := make([]occSnapshot, 0, len(affectedKeys))
250		for _, k := range affectedKeys {
251			occ := st.landmarks[k.id].appearances[k.num-1]
252			oldOcc = append(oldOcc, occSnapshot{key: k, occ: occ, x: occ.x, y: occ.y})
253		}
254		oldCorrLen := len(st.corrections)
255	
256		st.trajectory = next
257		for _, s := range oldOcc {
258			a := aggs[s.key]
259			s.occ.x, s.occ.y = a.x, a.y
260		}
261		st.corrections = append(st.corrections, rec)
262		st.corrIndex[req.ID] = canonicalCorrectionHash(req.Anchor, tgt)
263	
264		if err := m.saveReplace(); err != nil {
265			st.trajectory = oldTraj
266			for _, s := range oldOcc {
267				s.occ.x, s.occ.y = s.x, s.y
268			}
269			st.corrections = st.corrections[:oldCorrLen]
270			delete(st.corrIndex, req.ID)
271			return CorrectionRecord{}, err
272		}
273		return cloneRecord(rec), nil
274	}
275	
276	// Corrections 返回按提交次序排列的成功校正记录副本。记录一经生成永不
277	// 被后续校正改写；后续校正只是以当时最新状态为起点生成新记录。
278	func (m *Map) Corrections() ([]CorrectionRecord, error) {
279		m.mu.Lock()
280		defer m.mu.Unlock()
281		if m.closed {
282			return nil, ErrClosed
283		}
284		out := make([]CorrectionRecord, 0, len(m.state.corrections))
285		for _, rec := range m.state.corrections {
286			out = append(out, cloneRecord(rec))
287		}
288		return out, nil
289	}
290	
291	func (st *mapState) correctionRecordByID(id string) *CorrectionRecord {
292		for _, rec := range st.corrections {
293			if rec.ID == id {
294				return rec
295			}
296		}
297		return nil
298	}
299	
300	func cloneRecord(rec *CorrectionRecord) CorrectionRecord {
301		if rec == nil {
302			return CorrectionRecord{}
303		}
304		cp := *rec
305		cp.Poses = append([]PoseChange(nil), rec.Poses...)
306		cp.Landmarks = append([]LandmarkChange(nil), rec.Landmarks...)
307		return cp
308	}
309

