1	package posemap
2	
3	// occurrence.go 承载“观测按所在帧时间归入当时那次出现”这一业务规则，
4	// 供打开地图文件时的归属校验（validateLoaded）与回环校正时的出现归组
5	// （Correct）共同使用，保证两处对时间边界的判断始终一致。
6	
7	// occurrenceWindow 是一次出现接纳观测的时间边界：
8	//
9	//   - 已知首次观测时间的出现只接纳不早于该时间的观测（端点包含）；
10	//   - 已失效的出现仍接纳失效时间上的观测（端点包含），之后的观测不再
11	//     属于它；
12	//   - 仍有效的出现没有失效时间上界；
13	//   - 首次观测时间未知（旧文件缺少逐帧来源）的出现没有下界，继续接纳
14	//     更早的历史观测，不把零当作补造的开始时间。
15	//
16	// 同一路标各次出现的时间区间互不重叠（打开文件时由 validateLoaded 强制
17	// 校验，区间矛盾的文件按损坏拒绝），因此任一时刻至多有一次出现接纳
18	// 观测；旧观测永远归入它所在帧当时的那次出现，不因后来出现了更新的
19	// 有效记录而改属。
20	type occurrenceWindow struct {
21		hasFirstSeen  bool
22		firstSeenTime int64
23		active        bool
24		invalidTime   int64
25	}
26	
27	// owns 判断时间 t 的观测是否属于这次出现。
28	func (w occurrenceWindow) owns(t int64) bool {
29		if w.hasFirstSeen && t < w.firstSeenTime {
30			return false
31		}
32		if !w.active && t > w.invalidTime {
33			return false
34		}
35		return true
36	}
37	
38	// occurrenceNumberAt 把时间 t 的一次观测归入当时的那次出现，返回 1 起
39	// 的出现编号；没有任何出现接纳时返回 0。
40	func occurrenceNumberAt(wins []occurrenceWindow, t int64) int {
41		for i, w := range wins {
42			if w.owns(t) {
43				return i + 1
44			}
45		}
46		return 0
47	}
48	
49	// window 返回该出现状态对应的时间边界。
50	func (o *occurrenceState) window() occurrenceWindow {
51		return occurrenceWindow{
52			hasFirstSeen:  o.hasFirstSeen,
53			firstSeenTime: o.firstSeenTime,
54			active:        o.active,
55			invalidTime:   o.invalidTime,
56		}
57	}
58	
59	// occurrenceAt 把时间 t 的观测归入该路标当时的那次出现，返回 1 起的
60	// 出现编号；不属于任何出现时返回 0。
61	func (lm *landmarkState) occurrenceAt(t int64) int {
62		for i, o := range lm.appearances {
63			if o.window().owns(t) {
64				return i + 1
65			}
66		}
67		return 0
68	}
69	
70	// occurrenceWindowsOf 从文件记录中提取一个路标各次出现的时间边界，供
