package main

import (
	"fmt"
	"math"
)

// Scenario: merge dist 1, heading always 0, all poses (0,0) before correction.
// frame100 obs -> (0,0). frame200 local obs (0,+5/8),(0,-5/8). frame300 (0,-5/8).
// Correction: anchor 200 -> (ax, 1/40), heading 0 (pure translation).
func main() {
	const r = 5.0 / 4
	ax := math.Sqrt(231) / 20
	ay := 13.0 / 20
	fmt.Printf("r=%v ax=%v\n", r, ax)
	// import legality, both orders
	up := [2]float64{0, 5.0 / 8}
	down := [2]float64{0, -5.0 / 8}
	sim := func(order [][2]float64) (float64, float64, int, bool) {
		mx, my := 0.0, 0.0
		n := 1 // frame100 obs at (0,0)
		for _, p := range order {
			if n > 0 {
				d := math.Hypot(p[0]-mx, p[1]-my)
				if d > 1+1e-12 {
					return mx, my, n, false
				}
			}
			mx += (p[0] - mx) / float64(n+1)
			my += (p[1] - my) / float64(n+1)
			n++
		}
		return mx, my, n, true
	}
	mx, my, n, ok := sim([][2]float64{up, down, down})
	fmt.Printf("import order1: mean=(%v,%v) n=%d ok=%v (want 0,-5/32=-0.15625, 4)\n", mx, my, n, ok)
	mx2, my2, n2, ok2 := sim([][2]float64{down, up, down})
	fmt.Printf("import order2: mean=(%v,%v) n=%d ok=%v\n", mx2, my2, n2, ok2)

	// corrected positions
	Ap := [2]float64{ax, ay}                 // (ax, .65)
	Bp := [2]float64{ax, -3.0 / 5}           // (ax,-.6)
	Cp := [2]float64{ax, -3.0 / 5}
	fmt.Printf("|A'|=%v (want 1), |B'|=%v\n", math.Hypot(Ap[0], Ap[1]), math.Hypot(Bp[0], Bp[1]))

	replay := func(order [][2]float64) (string, float64, float64, int) {
		mx, my := 0.0, 0.0
		n := 1
		for idx, p := range order {
			d := math.Hypot(p[0]-mx, p[1]-my)
			who := []string{"A'", "B'", "C'"}[idx]
			fmt.Printf("  %s dist from running mean (%v,%v) = %.12f\n", who, mx, my, d)
			if d > 1+1e-12 {
				return who, mx, my, n
			}
			mx += (p[0] - mx) / float64(n+1)
			my += (p[1] - my) / float64(n+1)
			n++
		}
		return "", mx, my, n
	}
